css:
body {
    font-family: Arial, sans-serif;
    font-size: 12px;
    margin: 30px;
}

.voucher-header {
    text-align: center;
}

.voucher-header h2 {
    margin: 0;
}

.meta, .main-table, .inner-table, .amount-summary {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
}

.meta td {
    padding: 4px;
    vertical-align: top;
}

.main-table th, .main-table td,
.inner-table td, .amount-summary td {
    border: 1px solid #000;
    padding: 6px;
}

.inner-table {
    margin-top: 10px;
}

.amount-summary {
    margin-top: 20px;
}

.footer-signatures {
    margin-top: 50px;
    display: flex;
    justify-content: space-between;
    font-weight: bold;
}

html:
{% set money_in_words = frappe.utils.money_in_words %}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sales Invoice</title>
    <style>
       /* Main Styling */
        /*body {*/
        /*    font-family: Arial, sans-serif;*/
        /*    font-size: 8px;*/
        /*    margin: 0;*/
        /*    padding: 0;*/
        /*}*/

        .main-table {
            border-style: hidden !important; 
            border-bottom: 1px solid black !important; 
            border-left: 1px solid black !important; 
            border-right: 1px solid black !important;
            width: 100%; 
            table-layout: fixed;
            border-collapse: collapse;
        }

        .main-table th, .main-table td {
            border: 1px solid #000;
            padding: 6px;
            vertical-align: top;
            overflow: hidden;
        }

        /* Header Styles */
        .company-header {
            margin-bottom: 15px;
            border-bottom: 2px solid #000;
        }

        .company-info {
            display: flex;
            align-items: center;
        }

        .company-info img {
            width: 50px;
            height: 60px;
            margin-right: 5px;
        }

        .section-header {
            font-weight: bold;
            padding: 4px;
        }

        .tax-table {
            width: 100%;
            border-collapse: collapse;
        }

        .tax-table th, .tax-table td {
            border: 1px solid #000;
            padding: 6px;
            text-align: right;
        }

        /* Utility Classes */
        .text-right { text-align: right; }
        .text-center { text-align: center; }
        .text-left { text-align: left; }

        .amount_in_words{
            border-style: hidden !important; 
            border-bottom: 1px solid black !important; 
            border-left: 1px solid black !important; 
            border-right: 1px solid black !important;
        }

        .tax-table{
            border-style: hidden !important; 
            border-bottom: 1px solid black !important; 
            border-left: 1px solid black !important; 
            border-right: 1px solid black !important;
        }

        .total-amount{
            border-style: hidden !important; 
            border-bottom: 1px solid black !important; 
            border-left: 1px solid black !important; 
            border-right: 1px solid black !important;
        }

        .tax-table th{
            color: #000;
        }

        .terms-page {
            margin-top: 20px;
            width: 100%;
            page-break-inside: avoid;
        }

        .terms-table {
            width: 100%;
            border: 1px solid #000;
            border-collapse: collapse;
            page-break-inside: avoid;
        }

        .terms-table td {
            border: 1px solid #000;
        }

        .terms-list {
            padding-left: 20px;
        }
        /* Footer styling */

        body {
            font-family: Arial, sans-serif;
            font-size: 8px;
            margin: 15px;
            margin-bottom: 5mm; 
            color: #000 !important;
        }
    /*    table {*/
    /*    page-break-inside: avoid;*/
    /*}*/

    tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }

      /* Footer styling for screen */
      .page-footer {
        margin-top: 20px;
        padding-top: 10px;
        border-top: 1px solid #000;
      }

      /* Footer styling for print */
      @media print {
        body {
          margin-bottom: 5mm !important; /* Ensure enough space for footer */
        }

        .page-footer {
          position: fixed;
          bottom: 0;
          height: 30mm;
          left: 0;
          right: 0;
          width: 100%;
          padding: 5px 0;
          background: white;
          border-top: 1px solid #000;
        }

        /* Prevent content from overlapping with footer */
        .content-block {
          /*page-break-inside: avoid;*/
          /*break-inside: avoid;*/
          /*height: 200px; */
          /*margin-bottom: 50mm !important;*/
        }
      }

      /* Table Structure */
      table {
        font-size: 8px;
        /*page-break-inside: always;*/
      }

      /* Responsive tables */
      @media (max-width: 768px) {
        .responsive-table {
          max-height: 400px;
          overflow-y: auto;
          border: 1px solid #ccc;
          display: block;
        }
        .responsive-table table {
          table-layout: auto !important;
          width: auto !important;
        }
      }

      @media print {
        .responsive-table {
          max-height: unset !important;
          overflow: visible !important;
          border: none !important;
        }
      }

      @page {
        margin-top: 5mm;
        margin-bottom: 0mm; /* Increased for footer */
        margin-left: 5mm;
        margin-right: 5mm;
                @bottom-right {
                    content: "Page " counter(page) " of " counter(pages);
                    font-size: 8px;
                }
      }
    </style>
</head>
<body>
<div class="main-content">
    <h3 style="text-align: center; font-weight: bold;">SALES INVOICE</h3>
    <!-- IRN and QR Code Section -->
    {% if doc.irn %}
        {% set e_invoice_log = frappe.db.get_value("e-Invoice Log", doc.irn, ("invoice_data", "signed_qr_code"), as_dict=True) %}

        {% if e_invoice_log %}
            {% set invoice_data = json.loads(e_invoice_log.invoice_data) %}
            {% set date_format = frappe.db.get_single_value("System Settings", 'date_format').replace("mm", "MM") %}

            <table style="width: 100%; margin-bottom: 2px;">
                <tr>
                    <td style="vertical-align: top;">
                        <strong>IRN:</strong> {{ doc.irn }}<br>
                        <strong>Ack No:</strong> {{ invoice_data.get("AckNo") if invoice_data.get("AckNo") else '' }}<br>
                        <strong>Ack Date:</strong> 
                        {{ frappe.utils.format_datetime(invoice_data.get("AckDt"), date_format) if invoice_data.get("AckDt") else '' }}
                    </td>
                    <td style="text-align: right; vertical-align: top; width: 140px;">
                        {% if e_invoice_log.signed_qr_code %}
                            {{ web_block('e-Invoice QR', values={'e_invoice_qr_text': e_invoice_log.signed_qr_code }) }}
                        {% else %}
                            <span>QR code not available</span>
                        {% endif %}
                    </td>
                </tr>
            </table>
        {% endif %}
    {% endif %}

    <!-- Header Section -->
    <table style="width: 100%; border-collapse: collapse;">
        <tr>
            <!-- Logo and Company Details -->
            <td style="border: 1px solid #000; padding: 8px; vertical-align: top; width: 50%;">
                <table>
                    <tr>
                        <td style="vertical-align: top; width: 100px;">
                            {% set company_name = frappe.db.get_single_value("Global Defaults", "default_company") %}
                            {% if company_name %}
                                {% set company = frappe.get_doc("Company", company_name) %}
                                {% if company.logo_for_printing %}
                                    <img src="{{ frappe.utils.get_url(company.logo_for_printing) }}" alt="Company Logo" width="100px" height="100px">
                                {% endif %}
                            {% endif %}
                        </td>
                        <td style="vertical-align: top; padding-left: 10px;">
                            <strong>SRINATH SANITARYWARES</strong><br>
                            #1010, Srinath Mansion, Dr. Rajkumar Road, Rajajinagar<br>
                            Bangalore, Karnataka - 560010<br>
                            8023303393, 8023303394<br>
                            <strong>Email: </strong>quote@srinathcollective.com, care@srinathcollective.com<br>
                            <strong>GSTIN: </strong>29AAIFS5015M1ZS<br>
                            <strong>PAN: </strong>AAIFS5015M<br>
                            <strong>WEBSITE: </strong>www.srinathcollective.com
                        </td>
                    </tr>
                </table>
            </td>

            <!-- Invoice Details -->
            <td style="border: 1px solid #000; vertical-align: top; width: 25%;">
                <p class="invoice"><strong>Invoice No. & Date: </strong> {{ doc.name }} , {{ doc.posting_date }}</p>
                <p class="invoice"><strong>Order No. & Date: </strong> {{ doc.name }} {{ doc.posting_date }}</p>
                <p class="invoice"><strong>PO No. & Date:</strong> {{ doc.po_no }} & {{ doc.po_date }}</p>
                <p class="invoice"><strong>Reference:</strong> {{ doc.source }}</p>
            </td>

            <!-- Sales Consultant & Transport Details -->
            <td style="border: 1px solid #000; padding: 8px; vertical-align: top; width: 25%;">
                <p class="invoice"><strong>E-Way No.:</strong> {{ doc.ewaybill or " " }}</p>
                <p class="invoice">
                    <strong>Sales Consultant:</strong> 
                    {% if doc.sales_team and doc.sales_team[0].sales_person %}
                        {{ doc.sales_team[0].sales_person }} 
                            ({{ frappe.db.get_value("Sales Person", doc.sales_team[0].sales_person, "custom_employee_phone_number") or 'N/A' }})
                    {% else %}
                        N/A
                    {% endif %}
                </p>
                <p class="invoice"><strong>Payment Mode:</strong> </p>
                <p class="invoice"><strong>Vehicle No.:</strong> {{ doc.vehicle_no or 'N/A'}}</p>
            </td>
        </tr>

        <tr>
            <td colspan="4" style="border: 1px solid #000; padding: 10px; text-align: left;">
                <strong>Remarks: </strong> {{ doc.remarks }}
            </td>
        </tr>

        <tr>
            <td colspan="2" style="border: 1px solid #000; padding: 8px; vertical-align: top;">
                <strong>Billed To:</strong><br>
                {{ doc.customer_name }}<br>
                {{ doc.address_display }}
                M- {{ doc.contact_mobile }}
            </td>
            <td colspan="2" style="border: 1px solid #000; padding: 8px; vertical-align: top;">
                <strong>Delivery (Shipped To):</strong><br>
                {{ doc.address_display }}
                M- {{ doc.contact_mobile }}
            </td>
        </tr>
    </table>

    <div class="responsive-table content-block">
    <table class="invoice-details main-table" style="width: 100%; margin-bottom: 10px; line-height: 8px;">
        <thead>
            <tr style="background-color: #fff; color: #000 !important; line-height: 0.9; font-weight: bold;">
                <th style="width: 6%; text-align: left;"><strong>SN</strong></th>
                <th style="width: 9%; text-align: left;"><strong>Item Code</strong></th>
                <th style="width: 18%; text-align: left; word-wrap: break-word;"><strong>Item Name</strong></th>
                <th style="width: 9%; text-align: left;"><strong>Specs</strong></th>
                <th style="width: 7%; text-align: center;"><strong>Color</strong></th>
                <th style="width: 7%; text-align: center;"><strong>Size</strong></th>
                <th style="width: 7%; text-align: center;"><strong>Pack</strong></th>
                <th style="width: 10%; text-align: center;"><strong>HSN</strong></th>
                <th style="width: 6%; text-align: center;"><strong>Qty</strong></th>
                <th style="width: 8%; text-align: right;"><strong>Rate</strong></th>
                <th style="width: 7%; text-align: right;"><strong>Disc%</strong></th>
                <th style="width: 10%; text-align: center; word-wrap: break-word;"><strong>Disc.Rate/pcs</strong></th>
                <th style="width: 10%; text-align: right;"><strong>Amount</strong></th>
            </tr>
        </thead>
        <tbody>
            {% set ns = namespace(total_qty=0, total_amount=0) %}
            {% for item in doc.items %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>
                <td class="text-left">{{ item.item_code }}</td>
                <td class="text-left" style="word-wrap: break-word;">{{ item.item_name }}</td>
                <td class="text-left">{{ item.specs or "N/A" }}</td>
                <td class="text-center">{{ item.color or "N/A" }}</td>
                <td class="text-center">{{ item.size or "N/A" }}</td>
                <td class="text-center">{{ item.pack or "N/A" }}</td>
                <td class="text-center">{{ item.gst_hsn_code or 'N/A' }}</td>
                <td class="text-center">{{ item.qty }}{{ item.uom }}</td>
                <td class="text-right">{{ item.rate }}</td>
                <td class="text-right">{{ item.discount_percentage }}%</td>
                <td class="text-center">{{ (item.net_amount / item.qty) | round(2) if item.qty else 0 }}</td>
                <td class="text-right">{{ item.net_amount }}</td>
            </tr>
            {% set ns.total_qty = ns.total_qty + (item.qty or 0) %}
            {% set ns.total_amount = ns.total_amount + (item.net_amount or 0) %}
            {% endfor %}

            <!-- Totals Row -->
            <tr style="font-weight: bold; background-color: #fff;">
                <td colspan="8" class="text-right">Total</td>
                <td class="text-center">{{ ns.total_qty }}</td>
                <td colspan="3"></td>
                <td class="text-right">{{ "%.2f"|format(ns.total_amount) }}</td>
            </tr>
        </tbody>
    </table>
    </div>

    <!--Tax & GST-->
    {% set ns = namespace(
        total_taxable=0, total_cgst=0, total_sgst=0, total_tax_amount=0, hsn_summary={}
    ) %}

    {% for item in doc.items %}
        {% set hsn_code = item.gst_hsn_code or 'N/A' %}
        {% set taxable_value = item.net_amount if item.net_amount else item.amount %}
        {% set cgst_amount = item.cgst_amount if item.cgst_amount else 0 %}
        {% set sgst_amount = item.sgst_amount if item.sgst_amount else 0 %}
        {% set cgst_rate = item.cgst_rate if item.cgst_rate else 0 %}
        {% set sgst_rate = item.sgst_rate if item.sgst_rate else 0 %}

        {% if ns.hsn_summary.get(hsn_code) %}
            {% set existing = ns.hsn_summary[hsn_code] %}
            {% set ns.hsn_summary = ns.hsn_summary.update({
                hsn_code: {
                    'taxable_value': existing.taxable_value + taxable_value,
                    'cgst_amount': existing.cgst_amount + cgst_amount,
                    'sgst_amount': existing.sgst_amount + sgst_amount,
                    'cgst_rate': cgst_rate,
                    'sgst_rate': sgst_rate
                }
            }) or ns.hsn_summary %}
        {% else %}
            {% set ns.hsn_summary = ns.hsn_summary.update({
                hsn_code: {
                    'taxable_value': taxable_value,
                    'cgst_amount': cgst_amount,
                    'sgst_amount': sgst_amount,
                    'cgst_rate': cgst_rate,
                    'sgst_rate': sgst_rate
                }
            }) or ns.hsn_summary %}
        {% endif %}
    {% endfor %}
<div class="content-block">
    <table class="tax-table" style="width: 70%; border-collapse: collapse; float: left; line-height: 1px;">
        <thead>
            <tr>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">HSN/SAC</th>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">TAXABLE VALUE</th>
                <th colspan="2" style="border: 1px solid #000; padding: 8px; text-align: center;">CENTRAL TAX</th>
                <th colspan="2" style="border: 1px solid #000; padding: 8px; text-align: center;">STATE TAX</th>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">TOTAL TAX AMOUNT</th>
            </tr>
            <tr>
                <th style="border: 1px solid #000; padding: 8px;"></th>
                <th style="border: 1px solid #000; padding: 8px;"></th>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">RATE (%)</th>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">AMOUNT</th>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">RATE (%)</th>
                <th style="border: 1px solid #000; padding: 8px; text-align: center;">AMOUNT</th>
                <th style="border: 1px solid #000; padding: 8px;"></th>
            </tr>
        </thead>
        <tbody>
            {% for hsn_code, values in ns.hsn_summary.items() %}
                {% set total_tax = values.cgst_amount + values.sgst_amount %}
                {% set ns.total_taxable = ns.total_taxable + values.taxable_value %}
                {% set ns.total_cgst = ns.total_cgst + values.cgst_amount %}
                {% set ns.total_sgst = ns.total_sgst + values.sgst_amount %}
                {% set ns.total_tax_amount = ns.total_tax_amount + total_tax %}

                <tr>
                    <td style="border: 1px solid #000; padding: 8px; text-align: center;">{{ hsn_code }}</td>
                    <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(values.taxable_value) }}</td>
                    <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ values.cgst_rate }}%</td>
                    <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(values.cgst_amount) }}</td>
                    <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ values.sgst_rate }}%</td>
                    <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(values.sgst_amount) }}</td>
                    <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(total_tax) }}</td>
                </tr>
            {% endfor %}

            <tr style="font-weight: bold;">
                <td style="border: 1px solid #000; padding: 8px; text-align: center;">Total</td>
                <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(ns.total_taxable) }}</td>
                <td></td>
                <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(ns.total_cgst) }}</td>
                <td></td>
                <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(ns.total_sgst) }}</td>
                <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ "%.2f"|format(ns.total_tax_amount) }}</td>
            </tr>
        </tbody>
    </table>

    <table class="total-amount" style="width: 29.50%; border-collapse: collapse; float: right; line-height: 1px;">
        <tr>
            <td style="border: 1px solid #000; padding: 8px; text-align: left;">Total Amount:</td>
            <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ doc.grand_total }}</td>
        </tr>
        <tr>
            <td style="border: 1px solid #000; padding: 8px; text-align: left;">Round Off:</td>
            <td style="border: 1px solid #000; padding: 8px; text-align: right;">{{ doc.rounding_adjustment }}</td>
        </tr>
        <tr>
            <td style="border: 1px solid #000; padding: 8px; text-align: left; font-weight: bold;">Final Amount:</td>
            <td style="border: 1px solid #000; padding: 8px; text-align: right; font-weight: bold;">{{ doc.rounded_total }}</td>
        </tr>
    </table>
</div>

<div style="clear: both;"></div>
    <!-- Total Amount -->
    <table class="amount_in_words" style="width: 70%;">
        <tr>
            <td style="font-size: 8px; font-weight: bold; border: 1px solid #000;">
                Amount Chargeable (in words): {{ doc.in_words }} <br>
                Tax Amount (in words): {{ money_in_words(ns.total_tax_amount or 0) }}
            </td>
        </tr>
        <tr>
            <td style="font-size: 8px;  border: 1px solid #000;">
                <b>Bank Details:</b> Standard Chartered Bank, A/C No. 45205000313, Branch - SADASHIVANAGAR,Bangalore, IFSC Code: SCBL0036106
            </td>
        </tr>
    </table>

    <div class="terms-page">
        <table class="terms-table">
            <tr>
                <td>
                    <ol class="terms-list">
                        <li>Goods once sold cannot be taken back or exchanged.</li>
                        <li>Please check the material before taking delivery.</li>
                        <li>An interest of 24% P.A. will be charged for payment delayed more than 7 days.</li>
                        <li>Subject to Bengaluru Jurisdiction.</li>
                        <li>We cannot be held responsible for any shade or size variation in Tiles since we are only dealers. In case of any complaint, the matter should be taken up with the manufacturer directly.</li>
                        <li>E&OE</li>
                    </ol>
                </td>
            </tr>
            <tr>
                <td class="text-center">
                    THIS IS A COMPUTER-GENERATED INVOICE
                </td>
            </tr>
        </table>
    </div>
</div>

<!-- Footer Section -->
<div class="page-footer">
    <table style="width: 100%; text-align: center; ">

        <tr>
            <td colspan="2" style="width: 70%; text-align: left;">
                <strong>Amount in Words:</strong> {{ doc.in_words }}
            </td>
            <td colspan="2" style="width: 30%; text-align: right;">
                <strong>
                    {{ doc.grand_total }}<br>
                    For SRINATH SANITARYWARES
                </strong>
            </td>
        </tr>

        <tr>
            <td style="height: 15px;"></td>
        </tr>

        <tr>
            <td style="width: 30%; text-align: left; vertical-align: top;">
                <strong>Customer's Signature:</strong><br>
                Invoice No. {{ doc.name }}
            </td>
            {% set get_fullname = frappe.get_fullname %}
            <td style="width: 30%; text-align: center; vertical-align: top;">
                <strong>Prepared By:</strong>
                {{ get_fullname(frappe.session.user) }}
            </td>
            <td style="width: 20%; text-align: center; vertical-align: top;">
                <strong>Checked By:</strong>
            </td>
            <td style="width: 20%; text-align: right; vertical-align: top;">
                <strong>Authorised Signatory</strong>
            </td>
        </tr>
    </table>
</div>
</body>
</html>

