html:
{% set currency_symbol = frappe.get_doc("Currency", doc.currency).symbol if doc.currency else "₹" %}
<style>
    /* General Styling */
    body { font-family: Arial, sans-serif; font-size: 10px; margin: 0; padding: 0; }
    .header, .footer { text-align: center; font-weight: bold; }

    .table {
        width: 100%;
        border-collapse: collapse;
        border: 1px solid black;
        font-size: 9px;
    }

    .table th, .table td {
        border: 1px solid black;
        padding: 2px !important;
        text-align: left;
    }

    .right { text-align: right; }
    .bold { font-weight: bold; }
    .amount { text-align: right; }
    .bordered { border: 1px solid black; padding: 10px; }
    .signature { margin-top: 30px; text-align: right; font-weight: bold; }
    .item-image { width: 50px; height: 50px; object-fit: contain; }

    /* Border Fix */
    .bordered-line {
        border-bottom: 1px solid black;
        width: 100%;
        padding: 2px 0;
        margin: 0;
    }

    .bordered-line:last-child {
        border-bottom: none;
    }

    td { padding: 2px !important; }
    table { margin: 0; padding: 0; border-spacing: 0; }

    /* Hide Old Header */
    .header-container {
        display: none;
    }
</style>

<!-- Header with Logo & Centered Title in Same Line -->
<table width="100%" style="margin-bottom: 0;">
    <tr>
        <td style="width: 150px; text-align: left; vertical-align: middle;">
            {% set company_name = frappe.db.get_single_value("Global Defaults", "default_company") %}
  {% if company_name %}
    {% set company = frappe.get_doc("Company", company_name) %}
