            <img src="{{ frappe.utils.get_url(company.logo_for_printing) }}" 
                 alt="Company Logo" 
                 style="width: 60px; height: 50px; display: block; max-width: 100%; height: auto;">
    {% endif %}
  {% endif %}
        </td>
        <td style="text-align: center; vertical-align: middle;">
            <h1 style="margin: 0; font-weight: bold;">Sales Order</h1>
        </td>
        <td style="width: 120px;"></td>
    </tr>
</table>

<!-- Sales Order Details Table -->
<table class="table">
    <tr>
        <td colspan="2" class="bordered">
            <strong>SRINATH SANITARYWARES</strong><br>
            #1010, Srinath Mansion, Dr. Rajkumar Road,<br>
            Rajajinagar<br>
            Bangalore Karnataka - 560010<br>
            8023303393<br>
            <strong>GSTIN: 29AAIFS5015M1ZS</strong>
        </td>

        <td class="bordered">
            <div class="bordered-line"><strong>Sales Order No:</strong> {{ doc.name }}</div>
            <div class="bordered-line"><strong>Sales Person Name:</strong> 
                {% if doc.sales_team and doc.sales_team|length > 0 %}
                    {{ doc.sales_team[0].sales_person }}
                {% else %}
                    N/A
                {% endif %}
            </div>
        <div class="bordered-line"><strong>PO No.:</strong> {{ doc.custom_customer_po }}</div>
        <div class="bordered-line"><strong>Order Type:</strong> {{ doc.order_type or 'N/A' }}</div>
        </td>

        <td class="bordered">
            <div class="bordered-line"><strong>Date: </strong>{{ frappe.utils.formatdate(doc.transaction_date, "dd MMM yyyy") }}</div>
            <!--<div class="bordered-line"><strong>Mobile No.: </strong>9513177399</div>-->

            <!--code start => this line fetch the sales person number in user doctype through passing multiple linking doctype-->
            {% if doc.sales_team %}
                {% set sp_doc = frappe.get_doc("Sales Person", doc.sales_team[0].sales_person) %}
                {% if sp_doc.employee %}
                    {% set emp = frappe.get_doc("Employee", sp_doc.employee) %}
                    {% if emp.user_id %}
                        {% set user = frappe.get_doc("User", emp.user_id) %}
                        <div class="bordered-line"><strong>Mobile No.: </strong>{{ user.mobile_no or "Not Available" }}</div>
                    {% else %}
                        <div class="bordered-line"><strong>Mobile No.: </strong>User not linked</div>
                    {% endif %}
                {% else %}
                    <div class="bordered-line"><strong>Mobile No.: </strong></div>
                {% endif %}
            {% else %}
                <div class="bordered-line"><strong>Mobile No.: </strong>Not Assigned</div>
            {% endif %}

            <!--code end-->

            <div class="bordered-line"><strong>PO Date: </strong> {{ doc.po_date }} </div>
            <div class="bordered-line"><strong>Reference: </strong> {{ doc.source }} </div>
        </td>
    </tr>
    <!-- Buyer and Delivery Info -->
    <tr>
        <td colspan="2" class="bordered">
            <strong>Buyer Info:</strong><br>
            {{ doc.customer_name }}<br>
            {{ doc.customer_address or '-' }}<br>
            {{ doc.contact_mobile or '-' }}
        </td>
        <td colspan="2" class="bordered">
            <strong>Delivery Info:</strong><br>
            {{ doc.shipping_address_name or '-' }}
        </td>
    </tr>
</table>

<!-- Items Table -->
<table class="table">
    <thead>
        <tr>
            <th style="color: #000;">SR NO.</th>
            <th style="color: #000;">DESCRIPTION OF GOODS</th>
            <th style="color: #000;">BRAND</th>
            <th style="color: #000;">QUANTITY</th>
            <th style="color: #000">NRP</th>
            <th style="color: #000;">RATE</th>
            <th style="color: #000;">DISCOUNT (%)</th>
            <th style="color: #000;" class="amount">AMOUNT</th>
            <th style="color: #000;">IMAGE</th>
        </tr>
    </thead>
    <tbody>
        {% for item in doc.items %}
        <tr>
            <td>{{ loop.index }}</td>
            <td>{{ item.item_name}}</td>
            <td>
              {% set brand = frappe.db.get_value('Item', item.item_code, 'brand') %}
              {{ frappe.db.get_value('Brand', brand, 'description') or '' }}
            </td>
            <td>
                {% set uom_list = frappe.get_all("UOM Conversion Detail", filters={"parent": item.item_code}, fields=["uom"]) %}
                {% set uoms = uom_list | map(attribute='uom') | list %}

                {# Count distinct UOMs #}
                {% set uom_count = uoms|unique|list|count %}

                {# Check if any custom field has value #}
                {% set has_custom_values = item.custom_box or item.custom_sqft or item.custom_pcs %}

                {% if uom_count > 1 and has_custom_values %}
                    {# Show custom fields only when multiple UOMs AND custom values exist #}
                    {% if 'Box' in uoms and item.custom_box %}
                        {{ item.custom_box }} Box<br>
                    {% endif %}
                    {% if 'Sqft' in uoms and item.custom_sqft %}
                        {{ item.custom_sqft }} Sqft<br>
                    {% endif %}
                    {% if 'Pcs' in uoms and item.custom_pcs %}
                        {{ item.custom_pcs }} Pcs<br>
                    {% endif %}
                {% else %}
                    {# Show simple qty + uom in all other cases #}
                    {{ item.qty }} {{ item.uom }}
                {% endif %}
            </td>
            {% set base_rate = frappe.db.get_value("Item Price", {"item_code": item.item_code, "price_list": "Standard Selling"}, "price_list_rate") or 0 %}
            {% set tax_percent = (item.igst_rate or 0) + (item.cgst_rate or 0) + (item.sgst_rate or 0) %}
            {% set rate_incl_tax = base_rate * (1 + (tax_percent / 100)) %}
            {% set discount_percent = item.discount_percentage or 0 %}
            {% set net_rate = rate_incl_tax * (1 - (discount_percent / 100)) %}

            <td style="border: 1px solid #000; padding: 5px; text-align: left;">
                {{ frappe.format(net_rate, "Currency") }}
            </td>
            <td class="amount">{{ frappe.format(item.rate, "Currency") }}</td>
            <td class="amount">{{ item.discount_percentage or 0 }}</td>
            <td class="amount">{{ frappe.format(item.amount, "Currency") }}</td>
            <td>
                {% if item.image %}
                    <img src="{{ item.image }}" alt="Item Image" class="item-image">
                {% else %}
                    No Image
                {% endif %}
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>

<!-- Brand-Wise Discount Table -->
<table class="table" style="margin-bottom: 10px;">
    <thead>
        <tr>
            <th>BRAND NAME</th>
            <th style="color: #000;" class="amount">BRAND TOTAL AMOUNT</th>
