            <th style="color: #000;" class="amount">TOTAL VALUE</th>
        </tr>
    </thead>
    <tbody>
        {% set ns = namespace(overall_discount=0, total_amount=0) %}
        {% for item in doc.custom_dicount_table %}
        <tr>
            <td>{{ item.brand }}</td>
            <td class="amount">{{ frappe.format(item.value, "Currency") }}</td>
            <td class="amount">{{ item.disc_ }}</td>
            <td class="amount">{{ frappe.format(item.discount_amount, "Currency") }}</td>
            <td class="amount">{{ frappe.format(item.total_value, "Currency") }}</td>
        </tr>

        {# Update the namespace variables with the values from the table #}
        {% set ns.overall_discount = ns.overall_discount + (item.discount_amount or 0) %}
        {% set ns.total_amount = ns.total_amount + (item.total_value or 0) %}
        {% endfor %}

        <tr class="bold">
            <td colspan="3" class="right">Total Discount:</td>
            <td class="amount">{{ frappe.format(ns.overall_discount, "Currency") }}</td>
            <td></td>
        </tr>
        <tr class="bold">
            <td colspan="3" class="right">Total Value:</td>
            <td class="amount">{{ frappe.format(ns.total_amount, "Currency") }}</td>
            <td></td>
        </tr>
    </tbody>
</table>


<!-- Summary Table -->
<table class="table">
    <tr>
        <td class="right bold">Total Boxes:</td>
        <td class="amount"> #### </td>
    </tr>
    <tr>
        <td class="right bold">Material Cost:</td>
        <td class="amount">{{ frappe.format(doc.grand_total, "Currency") }}</td>
    </tr>
    <tr>
        <td class="right bold">Round Off:</td>
