    <tr>
        <td colspan="4" style="border: 1px solid #ccc; padding: 10px; text-align: left; background-color: #f1f1f1;">
            <strong>Amount Chargeable (in words):</strong> {{ frappe.utils.money_in_words(doc.rounded_total) }}
