html:
{% block style %}
<style>
    table {
        font-size: 12px;
    }
    .delivery-note {
        font-family: Arial, sans-serif;
        font-size: 12px;
        width: 99.50%;
        border-collapse: collapse;
    }
    .delivery-note th, .delivery-note td {
        border: 1px solid #000;
        padding: 5px;
        text-align: left;
        vertical-align: top;
    }
    .header {
        text-align: center;
        font-size: 16px;
        font-weight: bold;
        margin-bottom: 10px;
    }
    .company-info {
        text-align: center;
        font-size: 12px;
    }
    .logo {
        width: 120px;
        height: 100px;
    }
    .total-row {
        font-weight: bold;
        text-align: right;
        background-color: #f0f0f0;
    }
    .signature {
        width: 100%;
        text-align: right;
        padding-top: 40px;
    }
</style>
{% endblock %}

{% block content %}
<table width="100%">
      <tr>
        <!-- Left: Logo -->
        <td style="width: 150px; text-align: left; vertical-align: middle;">
  {% set company_name = frappe.db.get_single_value("Global Defaults", "default_company") %}
  {% if company_name %}
    {% set company = frappe.get_doc("Company", company_name) %}
    {% if company.logo_for_printing %}
      <img src="{{ frappe.utils.get_url(company.logo_for_printing) }}" alt="Company Logo" 
           style="width: 70px; height: auto; display: block; max-width: 100%;">
    {% endif %}
  {% endif %}
</td>



        <!-- Center: Title -->
        <td style="text-align: center; vertical-align: middle;">
           <strong>SRINATH SANITARYWARES</strong><br>
            #1010, Srinath Mansion, Dr. Rajkumar Road, Rajajinagar, Bangalore - 560010<br>
            Karnataka, Contact: +91-80-23303393 (4 Lines), +91-80-41285850<br>
            GSTIN: 29AAIFS5015M1ZS
        </td>

        <!-- Right: Empty space to balance alignment -->
        <td style="width: 120px;"></td>
      </tr>
    </table>

<div class="header">Delivery Note</div>

<!-- Fetching From Warehouse Details Dynamically -->
{% if doc.set_warehouse %}
  {% set from_warehouse_details = frappe.get_doc("Warehouse", doc.set_warehouse) %}
{% else %}
  {% set from_warehouse_details = {} %}
{% endif %}


<!-- From, To & Transfer Details in One Row -->
<table width="100%">
    <tr>
        <!-- (From & To) -->
        <td width="60%" style="vertical-align: top;">
            <strong>From:</strong> {{ from_warehouse_details.warehouse_name or '' }}<br>
            {{ from_warehouse_details.address_line_1 or '' }} {{ from_warehouse_details.address_line_2 or '' }}<br>
            {{ from_warehouse_details.city or '' }}, {{ from_warehouse_details.state or '' }} - {{ from_warehouse_details.pin or '' }}<br>
            <strong>Phone:</strong> {{ from_warehouse_details.mobile_no or 'N/A' }}<br>
            <strong>GSTIN:</strong> {{ from_warehouse_details.gstin or 'N/A' }}<br>


            <strong>To:</strong> {{ doc.customer_address }}<br>
            {{ doc.address_display | replace("\n", " ") | safe }}  {# No line breaks #}
            <strong>Phone:</strong> {{ doc.custom_mobile_no or 'N/A' }}<br>
            <strong>GSTIN:</strong> {{ doc.customer_gstin or 'N/A' }}
        </td>

        <!-- Right Section (Transfer Details) WITH SPACING -->
        <td width="40%" style="vertical-align: top;">
            <table width="100%">
                <tr><td><strong>Transfer ID:</strong></td><td style="padding-bottom: 5px;">{{ doc.name }}</td></tr>
                <tr><td><strong>Transferred By:</strong></td><td style="padding-bottom: 5px;">{{ doc.driver_name }}</td></tr>
                <tr><td><strong>Due Date:</strong></td><td style="padding-bottom: 5px;">{{ doc.lr_date }}</td></tr>
                <tr><td><strong>Vehicle No:</strong></td><td style="padding-bottom: 5px;">{{ doc.vehicle_no }}</td></tr>
                <tr><td><strong>Transporter:</strong></td><td style="padding-bottom: 5px;">{{ doc.transporter }}</td></tr>
                <tr><td><strong>E-way No:</strong></td><td style="padding-bottom: 5px;">####</td></tr>
            </table>
        </td>
    </tr>
</table>

<!-- Items Table -->
<table class="delivery-note" width="99.50%">
    <tr>
        <th>#</th>
        <th>Item Name</th>
        <th>HSN</th>
        <th>Quantity</th>
        <th>Price</th>
        <th>Total</th>
    </tr>

    {% set ns = namespace(grand_total=0) %}  

    {% for item in doc.items %}
    <tr>
        <td>{{ loop.index }}</td>
        <td>{{ item.item_name }}</td>
        <td>{{ item.hsn_code or 'N/A' }}</td>
        <td>{{ item.qty }}</td>
        <td>{{ item.rate }}</td>
        <td>{{ "%.2f"|format(item.amount) }}</td>
    </tr>
    {% set ns.grand_total = ns.grand_total + item.amount %} 
    {% endfor %}

    <!-- Total Row -->
    <tr class="total-row">
        <td colspan="5">Total</td>
        <td>{{ "%.2f"|format(ns.grand_total) }}</td>
    </tr>
</table>

<!-- Signature Section-->
<div class="signature">
    <p style="text-align: center;">{{ frappe.db.get_value("User", doc.owner, "full_name") }}</p>
    <p><strong>Authorized Signature</strong></p>
</div>
{% endblock %}

